function Initialize-WinToolFeatureView {
    $hostPanel = Get-WinToolUi -Name "FeatureList"
    $hostPanel.Children.Clear()
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($feature in @(Get-WinToolNote -Object (Get-WinToolFeatureCatalog) -Name "features" -Default @())) {
        $panel = New-Object System.Windows.Controls.Grid
        $panel.Height = 72
        $panel.Margin = [System.Windows.Thickness]::new(10, 0, 10, 0)
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $panel.ColumnDefinitions.Add((New-WinToolColumn))
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $checkbox = New-Object System.Windows.Controls.CheckBox
        $checkbox.VerticalAlignment = "Center"
        $checkbox.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
        $checkbox.IsEnabled = $false
        [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)
        [void]$panel.Children.Add($checkbox)
        $text = New-Object System.Windows.Controls.StackPanel
        $text.VerticalAlignment = "Center"
        $name = New-WinToolText -Text ([string]$feature.name) -Weight "SemiBold"
        $name.TextTrimming = "CharacterEllipsis"
        [void]$text.Children.Add($name)
        $about = New-WinToolText -Text ([string]$feature.description) -Brush "BrushMuted" -Margin ([System.Windows.Thickness]::new(0, 2, 12, 0))
        $about.TextTrimming = "CharacterEllipsis"
        [void]$text.Children.Add($about)
        [System.Windows.Controls.Grid]::SetColumn($text, 1)
        [void]$panel.Children.Add($text)
        $pill = New-Object System.Windows.Controls.Border
        $pill.Width = 176
        $pill.Height = 28
        $pill.CornerRadius = [System.Windows.CornerRadius]::new(14)
        $pill.VerticalAlignment = "Center"
        $pill.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushNavHover")
        $state = New-WinToolText -Text "Checking..." -Brush "BrushMuted"
        $state.Width = 160
        $state.TextAlignment = "Center"
        $state.HorizontalAlignment = "Center"
        $state.VerticalAlignment = "Center"
        $state.TextTrimming = "CharacterEllipsis"
        $pill.Child = $state
        [System.Windows.Controls.Grid]::SetColumn($pill, 2)
        [void]$panel.Children.Add($pill)
        $rowBorder = New-Object System.Windows.Controls.Border
        $rowBorder.Height = 72
        $rowBorder.BorderThickness = [System.Windows.Thickness]::new(0, 0, 0, 1)
        $rowBorder.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
        $rowBorder.Child = $panel
        [void]$hostPanel.Children.Add($rowBorder)
        $rows.Add([pscustomobject]@{
            Feature = $feature
            Checkbox = $checkbox
            StateText = $state
            Pill = $pill
            Status = "Unknown"
        })
    }
    $script:WinToolState.FeatureRows = $rows.ToArray()
    Add-WinToolAdminBadgeNear -Name "FeatureApply" -Place "Before" | Out-Null
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureRefresh") -EventName "Click" -Name "Features: refresh state" -Action {
        Start-WinToolFeatureDetection
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureApply") -EventName "Click" -Name "Features: apply changes" -Action {
        Invoke-WinToolFeatureApplyClick
    }
}

$script:WinToolFeatureTimeoutSeconds = 120

function Start-WinToolFeatureDetection {
    if ($null -ne $script:WinToolState.FeatureJob -or $script:WinToolState.Busy) {
        return
    }
    if (-not (Test-WinToolWindows)) {
        return
    }
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = $false
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $row.StateText.Text = (Get-WinToolText "msg.checking-ellipsis")
        $row.Checkbox.IsEnabled = $false
        foreach ($name in @($row.Feature.names)) {
            $names.Add([string]$name)
        }
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = (Get-WinToolText "msg.reading-the-current-state")
    $job = Start-WinToolScriptJob -ScriptText (Get-WinToolFeatureStateScript) -Argument @(, $names.ToArray())
    $job | Add-Member -NotePropertyName Started -NotePropertyValue ([DateTime]::UtcNow)
    $script:WinToolState.FeatureJob = $job
}

function Test-WinToolFeatureDetectionTimeout {
    $job = $script:WinToolState.FeatureJob
    if ($null -eq $job -or $job.Sync.Done) {
        return
    }
    if (([DateTime]::UtcNow - $job.Started).TotalSeconds -lt $script:WinToolFeatureTimeoutSeconds) {
        return
    }
    Stop-WinToolThread -Job $job
    $script:WinToolState.FeatureJob = $null
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = (-not $script:WinToolState.Busy)
    (Get-WinToolUi -Name "FeatureStatus").Text = (Get-WinToolText "msg.reading-windows-features-took-too-long-press-refresh-to-")
    Write-WinToolLog -Message (Get-WinToolText "msg.windows-features-check-timed-out-press-refresh-to-try-ag") -Level "warn"
}

function Complete-WinToolFeatureDetection {
    $job = $script:WinToolState.FeatureJob
    if ($null -eq $job) {
        return
    }
    $ok = [bool]$job.Sync.Ok
    $errorMessage = [string]$job.Sync.Error
    $states = $job.Sync.States
    Stop-WinToolThread -Job $job
    $script:WinToolState.FeatureJob = $null
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = (-not $script:WinToolState.Busy)
    if (-not $ok) {
        (Get-WinToolUi -Name "FeatureStatus").Text = (Get-WinToolText "msg.could-not-read-the-windows-features")
        Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-read-the-windows-features-n") -f $errorMessage) -Level "warn"
        return
    }
    Set-WinToolFeatureState -State $states
}

function Set-WinToolFeatureState {
    param([hashtable]$State)
    $on = 0
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $status = Get-WinToolFeatureStatus -Feature $row.Feature -State $State
        $row.Status = $status
        switch ($status) {
            "On" { $row.StateText.Text = (Get-WinToolText "msg.on"); $on++ }
            "Off" { $row.StateText.Text = (Get-WinToolText "msg.off") }
            "Partial" { $row.StateText.Text = (Get-WinToolText "msg.partly-on") }
            default { $row.StateText.Text = (Get-WinToolText "msg.not-available-on-this-pc") }
        }
        $row.Checkbox.IsEnabled = ($status -ne "Unavailable")
        $row.Checkbox.IsChecked = ($status -eq "On")
        if ($null -ne $row.Pill) {
            $tone = switch ($status) {
                "On" { @("BrushOkSoft", "BrushOk") }
                "Partial" { @("BrushWarnSoft", "BrushWarn") }
                default { @("BrushNavHover", "BrushMuted") }
            }
            $row.Pill.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $tone[0])
            $row.StateText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $tone[1])
        }
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = (Get-WinToolCountText "msg.n-of-these-features-are-on-tick-or-untick-then-apply" $on)
}

function Get-WinToolFeatureChange {
    $enable = New-Object System.Collections.Generic.List[object]
    $disable = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        if ($row.Status -eq "Unavailable" -or $row.Status -eq "Unknown") {
            continue
        }
        $wanted = ($row.Checkbox.IsChecked -eq $true)
        if ($wanted -and $row.Status -ne "On") {
            $enable.Add($row.Feature)
        }
        elseif (-not $wanted -and $row.Status -ne "Off") {
            $disable.Add($row.Feature)
        }
    }
    return [pscustomobject]@{
        Enable = $enable.ToArray()
        Disable = $disable.ToArray()
    }
}

function Invoke-WinToolFeatureApplyClick {
    Start-WinToolSurfaceTiming -Name "Features apply"
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $change = Get-WinToolFeatureChange
    $total = @($change.Enable).Count + @($change.Disable).Count
    if ($total -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.no-windows-feature-changes-to-apply") -Level "warn"
        return
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($feature in @($change.Enable)) { $lines.Add((Get-WinToolText "msg.turn-on-n" ([string]$feature.name))) }
    foreach ($feature in @($change.Disable)) { $lines.Add((Get-WinToolText "msg.turn-off-n" ([string]$feature.name))) }
    $ok = Request-WinToolConfirmation -Message (Get-WinToolText "msg.change-these-windows-features-n" ($lines -join "`n")) -Title (Get-WinToolText "msg.windows-features")
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolFeaturePlan -Enable $change.Enable -Disable $change.Disable)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage (Get-WinToolText "msg.windows-features-changed-restart-the-pc-to-finish") -AfterDone "Start-WinToolFeatureDetection"
}
# endregion

# region src/UI/ConfigView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Show-WinToolConfigPanel {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [switch]$Quiet
    )
    if (-not $Quiet) {
        Start-WinToolSurfaceTiming -Name ("Config " + $Name)
    }
    # Once a section has been measured it stays Visible. Collapsing it throws
    # the layout away and the next click measures it again.
    if ($null -eq $script:WinToolConfigShown) {
        $script:WinToolConfigShown = @{}
    }
    foreach ($panel in @("Profile", "Winget", "Tweaks", "Dns", "Power")) {
        $script:WinToolConfigShown[$panel] = $true
    }
    foreach ($panel in @("Profile", "Winget", "Tweaks", "Dns", "Power")) {
        $element = Get-WinToolUi -Name ("ConfigPanel" + $panel)
        if ($null -eq $element) { continue }
        $element.Visibility = "Visible"
        if ($panel -eq $Name) {
            $element.Opacity = 1
            $element.IsHitTestVisible = $true
            [System.Windows.Controls.Panel]::SetZIndex($element, 2)
        }
        else {
            $element.Opacity = 0
            $element.IsHitTestVisible = $false
            [System.Windows.Controls.Panel]::SetZIndex($element, 0)
        }
    }
}


function Initialize-WinToolLanguageChoice {
    $box = Get-WinToolUi -Name "ConfigLanguage"
    $hint = Get-WinToolUi -Name "ConfigLanguageHint"
    $label = Get-WinToolUi -Name "ConfigLanguageLabel"
    if ($null -ne $label) {
        $label.Text = Get-WinToolText "config.language.label"
    }
    if ($null -ne $hint) {
        $hint.Text = Get-WinToolText "config.language.tip"
    }
    if ($null -eq $box) {
        return
    }
    $script:WinToolLanguageBoxSync = $true
    try {
        $box.Items.Clear()
        $auto = New-Object System.Windows.Controls.ComboBoxItem
        $auto.Content = Get-WinToolText "config.language.matchWindows"
        $auto.Tag = "auto"
        [void]$box.Items.Add($auto)
        foreach ($code in @(Get-WinToolAvailableLanguage)) {
            $item = New-Object System.Windows.Controls.ComboBoxItem
            $item.Content = Get-WinToolText ("language.name." + $code)
            $item.Tag = $code
            [void]$box.Items.Add($item)
        }
        $pref = [string]$script:WinToolLanguagePreference
        if ([string]::IsNullOrWhiteSpace($pref)) {
            $pref = "auto"
        }
        $selected = $null
        foreach ($item in $box.Items) {
            if ([string]$item.Tag -eq $pref) {
                $selected = $item
                break
            }
        }
        if ($null -eq $selected) {
            $selected = $auto
        }
        $box.SelectedItem = $selected
    }
    finally {
        $script:WinToolLanguageBoxSync = $false
    }
}

function Invoke-WinToolLanguageChoice {
    if ($script:WinToolLanguageBoxSync) {
        return
    }
    $box = Get-WinToolUi -Name "ConfigLanguage"
    if ($null -eq $box -or $null -eq $box.SelectedItem) {
        return
    }
    $tag = [string]$box.SelectedItem.Tag
    if ([string]::IsNullOrWhiteSpace($tag)) {
        $tag = "auto"
    }
    $prefs = Get-WinToolPreference
    $prefs.language = $tag
    Save-WinToolPreference -Preferences $prefs
    Initialize-WinToolLocale -Language $tag -Force | Out-Null
    Set-WinToolXamlText -Root $script:WinToolWindow
    if (Get-Command -Name Sync-WinToolHomeLocale -ErrorAction SilentlyContinue) {
        Sync-WinToolHomeLocale
    }
    Initialize-WinToolLanguageChoice
    Update-WinToolProfileSummary
    if ($null -ne $script:WinToolState) {
        $current = [string]$script:WinToolState.ActiveView
        $script:WinToolState.ViewShown = @($current)
        $script:WinToolConfigShown = @{}
    }
    if ($script:WinToolState.ActiveView -eq "Config") {
        Show-WinToolConfigPanel -Name "Profile" -Quiet
    }
    $status = Get-WinToolUi -Name "StatusText"
    if ($null -ne $status -and -not $script:WinToolState.Busy) {
        $status.Text = Get-WinToolText "status.ready"
    }
}

function Initialize-WinToolConfigView {
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "SaveProfile") -EventName "Click" -Name "Config: save profile" -Action { Invoke-WinToolSaveProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "LoadProfile") -EventName "Click" -Name "Config: load profile" -Action { Invoke-WinToolLoadProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ExportWinget") -EventName "Click" -Name "Config: export winget list" -Action { Invoke-WinToolExportWinget }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ImportWinget") -EventName "Click" -Name "Config: import winget list" -Action { Invoke-WinToolImportWinget }
    foreach ($tab in @(
            [pscustomobject]@{ Name = "ConfigTabProfile"; Panel = "Profile" },
            [pscustomobject]@{ Name = "ConfigTabWinget"; Panel = "Winget" },
            [pscustomobject]@{ Name = "ConfigTabTweaks"; Panel = "Tweaks" },
            [pscustomobject]@{ Name = "ConfigTabDns"; Panel = "Dns" },
            [pscustomobject]@{ Name = "ConfigTabPower"; Panel = "Power" }
        )) {
        Register-WinToolUiEvent -Control (Get-WinToolUi -Name $tab.Name) -EventName "Checked" -Name ("Config: " + $tab.Panel) -Data $tab.Panel -Action {
            param($source, $eventData, $panelName)
            $null = $source, $eventData
            Show-WinToolConfigPanel -Name $panelName
        }
    }
    Initialize-WinToolLanguageChoice
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ConfigLanguage") -EventName "SelectionChanged" -Name "Config: language" -Action { Invoke-WinToolLanguageChoice }
    Show-WinToolConfigPanel -Name "Profile" -Quiet
    Initialize-WinToolSystemView
    Update-WinToolProfileSummary
}

function Add-WinToolProfileHeading {
    param($Parent, [string]$Text)
    $heading = New-WinToolText -Text $Text -Weight "SemiBold" -Margin ([System.Windows.Thickness]::new(0, 8, 0, 4))
    [void]$Parent.Children.Add($heading)
}

function Add-WinToolProfileItem {
    param($Parent, [string]$Text, [switch]$Muted)
    $row = New-Object System.Windows.Controls.Border
    $row.Height = 36
    $row.BorderThickness = [System.Windows.Thickness]::new(0, 1, 0, 0)
    $row.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    $grid = New-Object System.Windows.Controls.Grid
    $grid.ColumnDefinitions.Add((New-WinToolColumn -Auto))
    $grid.ColumnDefinitions.Add((New-WinToolColumn))
    if (-not $Muted) {
        $dot = New-Object System.Windows.Shapes.Ellipse
        $dot.Width = 8
        $dot.Height = 8
        $dot.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
        $dot.VerticalAlignment = "Center"
        $dot.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, "BrushOk")
        [void]$grid.Children.Add($dot)
    }
    $brush = "BrushInk"
    if ($Muted) { $brush = "BrushMuted" }
    $label = New-WinToolText -Text $Text -Brush $brush
    $label.VerticalAlignment = "Center"
    $label.TextTrimming = "CharacterEllipsis"
    [System.Windows.Controls.Grid]::SetColumn($label, 1)
    [void]$grid.Children.Add($label)
    $row.Child = $grid
    [void]$Parent.Children.Add($row)
}

function Update-WinToolProfileSummary {
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $terminal = Get-WinToolTerminalChoice
    $prompt = "Oh My Posh"
    foreach ($entry in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())) {
        if ([string]$entry.id -eq [string]$terminal.prompt) {
            $prompt = [string]$entry.name
            break
        }
    }
    $replay = "Terminal setup is saved with the profile."
    if (-not $terminal.enabled) {
        $replay = "Terminal setup is not included when this profile is replayed."
    }
    $text = "{0} apps selected, {1} tweaks on. Prompt: {2}. {3}" -f $apps.Count, $tweaks.Count, $prompt, $replay
    (Get-WinToolUi -Name "ProfileSummary").Text = $text
    $preview = Get-WinToolUi -Name "ProfilePreview"
    if ($null -eq $preview) { return }
    $preview.Children.Clear()
    $shown = 6
    Add-WinToolProfileHeading -Parent $preview -Text ("Apps | {0}" -f $apps.Count)
    $appShown = 0
    foreach ($app in @($apps)) {
        if ($appShown -ge $shown) { break }
        Add-WinToolProfileItem -Parent $preview -Text ([string]$app.Name)
        $appShown++
    }
    if ($apps.Count -gt $shown) {
        Add-WinToolProfileItem -Parent $preview -Text ("+ {0} more" -f ($apps.Count - $shown)) -Muted
    }
    elseif ($apps.Count -eq 0) {
        Add-WinToolProfileItem -Parent $preview -Text "No apps selected" -Muted
    }
    Add-WinToolProfileHeading -Parent $preview -Text ("Tweaks | {0}" -f $tweaks.Count)
    $tweakShown = 0
    foreach ($tweak in @($tweaks)) {
        if ($tweakShown -ge $shown) { break }
        Add-WinToolProfileItem -Parent $preview -Text ([string]$tweak.name)
        $tweakShown++
    }
    if ($tweaks.Count -gt $shown) {
        Add-WinToolProfileItem -Parent $preview -Text ("+ {0} more" -f ($tweaks.Count - $shown)) -Muted
    }
    elseif ($tweaks.Count -eq 0) {
        Add-WinToolProfileItem -Parent $preview -Text "No tweaks on" -Muted
    }
    $theme = [string](Get-WinToolNote -Object $terminal -Name "promptStyle" -Default "")
    $fontId = [string](Get-WinToolNote -Object $terminal -Name "fontId" -Default "")
    $schemeId = [string](Get-WinToolNote -Object $terminal -Name "schemeId" -Default "")
    Add-WinToolProfileHeading -Parent $preview -Text "Terminal"
    if ($terminal.enabled) {
        Add-WinToolProfileItem -Parent $preview -Text $prompt
        if (-not [string]::IsNullOrWhiteSpace($theme)) { Add-WinToolProfileItem -Parent $preview -Text ("Theme: " + $theme) }
        if (-not [string]::IsNullOrWhiteSpace($fontId)) { Add-WinToolProfileItem -Parent $preview -Text ("Font: " + $fontId) }
        if (-not [string]::IsNullOrWhiteSpace($schemeId)) { Add-WinToolProfileItem -Parent $preview -Text ("Scheme: " + $schemeId) }
    }
    else {
        Add-WinToolProfileItem -Parent $preview -Text "Not included in saved profiles" -Muted
    }
}

function Get-WinToolProfileFromUi {
    if (-not $script:WinToolState.TweakStateRead) {
        Update-WinToolTweakState
    }
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in $apps) {
        $appIds.Add([string]$app.Id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in $tweaks) {
        $tweakIds.Add([string]$tweak.id)
    }
    return (ConvertTo-WinToolProfile -AppId $appIds.ToArray() -TweakId $tweakIds.ToArray() -Terminal (Get-WinToolTerminalChoice) -Name "My WinTool profile")
}

function Import-WinToolProfileToUi {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $toolProfile = Read-WinToolProfile -Path $Path
    $resolved = Resolve-WinToolProfileSelection -Profile $toolProfile
    foreach ($id in @($resolved.UnknownApps)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.unknown-app-id-n-in-the-profile" $id) -Level "warn"
    }
    foreach ($id in @($resolved.UnknownTweaks)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.unknown-tweak-id-n-in-the-profile" $id) -Level "warn"
    }
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in @($resolved.AppRecords)) {
        $appIds.Add([string]$app.id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in @($resolved.TweakRecords)) {
        $tweakIds.Add([string]$tweak.id)
    }
    Sync-WinToolAppCheck -Id $appIds.ToArray() -OnlyThese
    Sync-WinToolTweakCheck -Id $tweakIds.ToArray() -OnlyThese
    Sync-WinToolTerminalChoice -Selection (Get-WinToolNote -Object $toolProfile -Name "terminal")
    Update-WinToolProfileSummary
    Write-WinToolLog -Message ((Get-WinToolText "msg.loaded-n-nothing-was-installed-yet") -f $Path) -Level "ok"
}

function Invoke-WinToolSaveProfile {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $path = Select-WinToolDialogFile -Mode Save -Filter "WinTool profile (*.json)|*.json" -FileName "wintool-profile.json" -Title (Get-WinToolText "msg.save-wintool-profile") -DefaultExt ".json"
    if ([string]::IsNullOrWhiteSpace($path)) {
        return
    }
    try {
        $toolProfile = Get-WinToolProfileFromUi
        Write-WinToolProfile -Path $path -Profile $toolProfile
        Write-WinToolLog -Message ((Get-WinToolText "msg.saved-profile-to-n") -f $path) -Level "ok"
    }
    catch {
        Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-save-that-profile-n") -f $_.Exception.Message) -Level "error"
    }
}

function Invoke-WinToolLoadProfile {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $path = Select-WinToolDialogFile -Mode Open -Filter "WinTool profile (*.json)|*.json" -Title (Get-WinToolText "msg.load-wintool-profile")
    if ([string]::IsNullOrWhiteSpace($path)) {
        return
    }
    try {
        Import-WinToolProfileToUi -Path $path
    }
    catch {
        Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-load-that-profile-n") -f $_.Exception.Message) -Level "error"
    }
}

function Invoke-WinToolExportWinget {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.winget-was-not-found-install-app-installer-from-the-micr") -Level "warn"
        return
    }
    $path = Select-WinToolDialogFile -Mode Save -Filter "winget package list (*.json)|*.json" -FileName "winget-packages.json" -Title (Get-WinToolText "msg.export-winget-package-list") -DefaultExt ".json"
    if ([string]::IsNullOrWhiteSpace($path)) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = (Get-WinToolText "msg.export-winget-packages")
        FilePath = $winget
        Arguments = @("export", "-o", $path, "--accept-source-agreements")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage (Get-WinToolText "msg.winget-export-finished")
}

function Invoke-WinToolImportWinget {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message (Get-WinToolText "msg.winget-was-not-found-install-app-installer-from-the-micr") -Level "warn"
        return
    }
    $path = Select-WinToolDialogFile -Mode Open -Filter "winget package list (*.json)|*.json" -Title (Get-WinToolText "msg.import-winget-package-list")
    if ([string]::IsNullOrWhiteSpace($path)) {
        return
    }
    $ok = Request-WinToolConfirmation -Message (Get-WinToolText "msg.ask-winget-to-install-every-package-in-this-file") -Title (Get-WinToolText "ui.ImportWinget.Content")
    if (-not $ok) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = (Get-WinToolText "msg.import-winget-packages")
        FilePath = $winget
        Arguments = @("import", "-i", $path, "--accept-package-agreements", "--accept-source-agreements", "--disable-interactivity")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage (Get-WinToolText "msg.winget-import-finished") -AfterDone "Start-WinToolAppDetection"
}

function Initialize-WinToolSystemView {
    $catalog = Get-WinToolSystemCatalog
    $providerBox = Get-WinToolUi -Name "DnsProvider"
    $providerBox.Items.Clear()
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $catalog)) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = [string]$provider.name
        $item.Tag = [string]$provider.id
        $item.ToolTip = [string](Get-WinToolNote -Object $provider -Name "description" -Default "")
        [void]$providerBox.Items.Add($item)
    }
    $providerBox.SelectedIndex = 0
    $plan = Get-WinToolNote -Object $catalog -Name "powerPlan"
    (Get-WinToolUi -Name "PowerPlanDescription").Text = [string]$plan.description

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "DnsAdapter") -EventName "SelectionChanged" -Name "Config: pick adapter" -Action { Sync-WinToolDnsSummary }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RefreshDns") -EventName "Click" -Name "Config: refresh adapters" -Action { Update-WinToolSystemView }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ApplyDns") -EventName "Click" -Name "Config: apply DNS" -Action { Invoke-WinToolDnsClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AddUltimatePlan") -EventName "Click" -Name "Config: add Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "add" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RemoveUltimatePlan") -EventName "Click" -Name "Config: remove Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "remove" }
}

function Set-WinToolDnsAdapterList {
    param($Adapter)
    $adapters = @($Adapter)
    $script:WinToolState.DnsAdapters = $adapters
    $box = Get-WinToolUi -Name "DnsAdapter"
    $box.Items.Clear()
    if ($adapters.Count -gt 1) {
        $all = New-Object System.Windows.Controls.ComboBoxItem
        $all.Content = (Get-WinToolText "msg.all-connected-adapters")
        $all.Tag = -1
        [void]$box.Items.Add($all)
    }
    foreach ($adapter in $adapters) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = ("{0}  -  {1}" -f [string]$adapter.Name, [string]$adapter.Description)
        $item.Tag = [int]$adapter.Index
        [void]$box.Items.Add($item)
    }
    if ($box.Items.Count -gt 0) {
        $box.SelectedIndex = 0
    }
    Sync-WinToolDnsSummary
}

function Set-WinToolPowerPlanFromList {
    param([AllowEmptyString()][string]$Text)
    $status = "Power plans are only on Windows."
    $script:WinToolState.UltimatePlanAdded = $false
    if (Test-WinToolWindows) {
        try {
            $schemes = ConvertFrom-WinToolPowerList -Text $Text
            $catalog = Get-WinToolSystemCatalog
            $state = Get-WinToolPowerPlanState -Scheme $schemes -Catalog $catalog
            $status = Format-WinToolPowerPlanStatus -State $state -Name ([string]$catalog.powerPlan.name)
            $script:WinToolState.UltimatePlanAdded = [bool]$state.Added
        }
        catch {
            $status = (Get-WinToolText "msg.could-not-read-power-plans-n" $_.Exception.Message)
        }
    }
    (Get-WinToolUi -Name "RemoveUltimatePlan").IsEnabled = (-not $script:WinToolState.Busy -and [bool]$script:WinToolState.UltimatePlanAdded)
    (Get-WinToolUi -Name "PowerPlanStatus").Text = $status
}

function Update-WinToolSystemView {
    # A direct refresh stays on this thread so the status text is ready at once.
    # Opening the tab uses Start-WinToolSystemProbe instead.
    $script:WinToolState.SystemGeneration = [int]$script:WinToolState.SystemGeneration + 1
    $script:WinToolState.SystemChecked = $true
    $adapters = @()
    try {
        $adapters = @(Get-WinToolDnsAdapter)
    }
    catch {
        Write-WinToolLog -Message (Get-WinToolText "msg.could-not-read-network-adapters-n" $_.Exception.Message) -Level "warn"
    }
    Set-WinToolDnsAdapterList -Adapter $adapters
    Sync-WinToolPowerPlanStatus
}

function Start-WinToolSystemProbe {
    if ($script:WinToolState.SystemChecked) { return }
    if ($null -ne $script:WinToolState.SystemJob) { return }
    if ($script:WinToolHomeNoJobs) { return }
    if (-not (Test-WinToolWindows)) {
        $script:WinToolState.SystemChecked = $true
        return
    }
    $generation = [int]$script:WinToolState.SystemGeneration
    $job = Start-WinToolScriptJob -ScriptText (Get-WinToolSystemProbeScript)
    $job | Add-Member -NotePropertyName Generation -NotePropertyValue $generation
    $script:WinToolState.SystemJob = $job
    $script:WinToolState.SystemChecked = $true
}

function Complete-WinToolSystemProbe {
    $job = $script:WinToolState.SystemJob
    if ($null -eq $job) { return }
    $generation = 0
    if ($null -ne $job.PSObject.Properties["Generation"]) { $generation = [int]$job.Generation }
    $ok = [bool]$job.Sync.Ok
    $errorText = [string]$job.Sync.Error
    $packed = [string]$job.Sync.Adapters
    $power = [string]$job.Sync.Power
    $powerError = [string]$job.Sync.PowerError
    Stop-WinToolThread -Job $job
    $script:WinToolState.SystemJob = $null
    if ($generation -ne [int]$script:WinToolState.SystemGeneration) { return }
    if (-not $ok) {
        Write-WinToolLog -Message (Get-WinToolText "msg.could-not-read-network-adapters-n" $errorText) -Level "warn" -Diagnostic
        return
    }
    Set-WinToolDnsAdapterList -Adapter @(ConvertFrom-WinToolSystemProbe -Text $packed)
    if (-not [string]::IsNullOrWhiteSpace($powerError)) {
        $script:WinToolState.UltimatePlanAdded = $false
        (Get-WinToolUi -Name "RemoveUltimatePlan").IsEnabled = $false
        (Get-WinToolUi -Name "PowerPlanStatus").Text = (Get-WinToolText "msg.could-not-read-power-plans-n" $powerError)
        return
    }
    Set-WinToolPowerPlanFromList -Text $power
}

function Get-WinToolSelectedDnsAdapter {
    $item = (Get-WinToolUi -Name "DnsAdapter").SelectedItem
    if ($null -eq $item) {
        return @()
    }
    $index = [int]$item.Tag
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($adapter in @($script:WinToolState.DnsAdapters)) {
        if ($index -eq -1 -or [int]$adapter.Index -eq $index) {
            $list.Add($adapter)
        }
    }
    return $list.ToArray()
}

function Sync-WinToolDnsSummary {
    $selected = @(Get-WinToolSelectedDnsAdapter)
    $text = "No connected network adapter found."
    if ($selected.Count -gt 0) {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($adapter in $selected) {
            $lines.Add((Format-WinToolDnsSummary -Adapter $adapter))
        }
        $text = "Now: " + ($lines -join [Environment]::NewLine)
    }
    (Get-WinToolUi -Name "DnsCurrent").Text = $text
}

function Sync-WinToolPowerPlanStatus {
    $text = ""
    if (Test-WinToolWindows) {
        try {
            $text = ((& powercfg.exe /list) | Out-String)
        }
        catch {
            $script:WinToolState.UltimatePlanAdded = $false
            (Get-WinToolUi -Name "RemoveUltimatePlan").IsEnabled = $false
            (Get-WinToolUi -Name "PowerPlanStatus").Text = (Get-WinToolText "msg.could-not-read-power-plans-n" $_.Exception.Message)
            return
        }
    }
    Set-WinToolPowerPlanFromList -Text $text
}

function Invoke-WinToolDnsClick {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $adapters = @(Get-WinToolSelectedDnsAdapter)
    if ($adapters.Count -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.pick-a-network-adapter-first") -Level "warn"
        return
    }
    $item = (Get-WinToolUi -Name "DnsProvider").SelectedItem
    if ($null -eq $item) {
        Write-WinToolLog -Message (Get-WinToolText "msg.pick-a-dns-provider-first") -Level "warn"
        return
    }
    $provider = Find-WinToolDnsProvider -Id ([string]$item.Tag)
    $ipv6 = ((Get-WinToolUi -Name "DnsIncludeIpv6").IsChecked -eq $true)
    $servers = @(Get-WinToolDnsServerList -Provider $provider -IncludeIpv6 $ipv6)
    $what = "automatic (DHCP)"
    if ($servers.Count -gt 0) {
        $what = [string]$provider.name + " (" + ($servers -join ", ") + ")"
    }
    $names = (@($adapters | ForEach-Object { [string]$_.Name })) -join ", "
    $ok = Request-WinToolConfirmation -Message ((Get-WinToolText "msg.set-dns-on-n-to-n") -f $names, $what) -Title (Get-WinToolText "ui.ConfigTabDns.Content")
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolDnsPlan -Adapter $adapters -Provider $provider -IncludeIpv6 $ipv6)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "DNS servers changed." -AfterDone "Update-WinToolSystemView"
}

function Invoke-WinToolPowerPlanClick {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action
    )
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message (Get-WinToolText "drivers.scan.wait") -Level "warn"
        return
    }
    $message = "Add the Ultimate Performance power plan and switch to it?"
    if ($Action -eq "remove") {
        $message = "Remove the Ultimate Performance plan WinTool added? If it is active, Windows goes back to Balanced."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title (Get-WinToolText "msg.power-plan")
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolPowerPlanPlan -Action $Action)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Power plan updated." -AfterDone "Sync-WinToolPowerPlanStatus"
}
# endregion

# region src/UI/HomeView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# The Home page: a score ring, five checks in a fixed order and three small
# cards. Every state (analyzing, done, fixing) uses the same slots, so only
# the content inside them changes.

function Get-WinToolHomeEllipsis {
    return [string][char]0x2026
}

function Test-WinToolHomeReduceMotion {
    if ($script:WinToolHomeReduceMotion) { return $true }
    try { return (-not [System.Windows.SystemParameters]::ClientAreaAnimation) } catch { return $false }
}

function New-WinToolHomeBrush {
    param([string]$From, [string]$To, [switch]$Vertical, [double]$Alpha = 1)
    $brush = New-Object System.Windows.Media.LinearGradientBrush
    $brush.StartPoint = [System.Windows.Point]::new(0, 0)
    if ($Vertical) { $brush.EndPoint = [System.Windows.Point]::new(0, 1) } else { $brush.EndPoint = [System.Windows.Point]::new(1, 1) }
    $first = [System.Windows.Media.ColorConverter]::ConvertFromString($From)
    $second = [System.Windows.Media.ColorConverter]::ConvertFromString($To)
    if ($Alpha -lt 1) {
        $first = [System.Windows.Media.Color]::FromArgb([byte][Math]::Round(255 * $Alpha), $first.R, $first.G, $first.B)
        $second = [System.Windows.Media.Color]::FromArgb([byte]0, $second.R, $second.G, $second.B)
    }
    $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($first, 0)))
    $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($second, 1)))
    return $brush
}

function Get-WinToolHomeArcData {
    # Path data for an arc that starts at the top and runs clockwise.
    param([double]$CenterX, [double]$CenterY, [double]$Radius, [double]$Angle)
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    $sweep = [Math]::Max(0.5, [Math]::Min(359.6, $Angle))
    $radians = $sweep * [Math]::PI / 180
    $x = $CenterX + $Radius * [Math]::Sin($radians)
    $y = $CenterY - $Radius * [Math]::Cos($radians)
    $large = 0
    if ($sweep -gt 180) { $large = 1 }
    $text = [string]::Format($culture, "M {0},{1} A {2},{2} 0 {3} 1 {4:0.###},{5:0.###}", $CenterX, ($CenterY - $Radius), $Radius, $large, $x, $y)
    return [pscustomobject]@{ Data = $text; X = $x; Y = $y }
}

function Set-WinToolHomeArc {
    param([double]$Angle)
    $hs = $script:WinToolState.Home
    $hs.Arc = $Angle
    $arc = Get-WinToolUi -Name "HomeArc"
    $cap = Get-WinToolUi -Name "HomeArcCap"
    if ($Angle -lt 1) {
        $arc.Visibility = "Hidden"
        $cap.Visibility = "Hidden"
        return
    }
    $shape = Get-WinToolHomeArcData -CenterX 98 -CenterY 98 -Radius 78 -Angle $Angle
    $arc.Data = [System.Windows.Media.Geometry]::Parse($shape.Data)
    [System.Windows.Controls.Canvas]::SetLeft($cap, $shape.X - 6)
    [System.Windows.Controls.Canvas]::SetTop($cap, $shape.Y - 6)
    $arc.Visibility = "Visible"
    $cap.Visibility = "Visible"
}

function New-WinToolHomeRow {
    param(
        [Parameter(Mandatory = $true)]$Check,
        [bool]$Last
    )
    $border = New-Object System.Windows.Controls.Border
    $border.Height = 56
    $border.Padding = [System.Windows.Thickness]::new(14, 0, 14, 0)
    if (-not $Last) {
        $border.BorderThickness = [System.Windows.Thickness]::new(0, 0, 0, 1)
        $border.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    }
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($width in @(28, 12, -1, 12, 76)) {
        $column = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $column.Width = [System.Windows.GridLength]::new($width) }
        $grid.ColumnDefinitions.Add($column)
    }
    $border.Child = $grid

    $content = New-Object System.Windows.Controls.Grid
    [System.Windows.Controls.Grid]::SetColumnSpan($content, 3)
    $null = $grid.Children.Add($content)
    foreach ($width in @(28, 12, -1)) {
        $column = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $column.Width = [System.Windows.GridLength]::new($width) }
        $content.ColumnDefinitions.Add($column)
    }

    $icon = New-Object System.Windows.Controls.Grid
    $icon.Width = 22
    $icon.Height = 22
    $icon.VerticalAlignment = "Center"
    $disc = New-Object System.Windows.Shapes.Ellipse
    $disc.Width = 22
    $disc.Height = 22
    $glyph = New-Object System.Windows.Shapes.Path
    $glyph.StrokeThickness = 2
    $glyph.StrokeStartLineCap = "Round"
    $glyph.StrokeEndLineCap = "Round"
    $glyph.StrokeLineJoin = "Round"
    $spinner = New-Object System.Windows.Shapes.Path
    $spinner.StrokeThickness = 2
    $spinner.StrokeStartLineCap = "Round"
    $spinner.StrokeEndLineCap = "Round"
    $spinner.Data = [System.Windows.Media.Geometry]::Parse("M 11,3 A 8,8 0 0 1 19,11")
    $spinner.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, "BrushAccent")
    $spinner.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
    $spinner.RenderTransform = New-Object System.Windows.Media.RotateTransform(0)
    $spinner.Width = 22
    $spinner.Height = 22
    $null = $icon.Children.Add($disc)
    $null = $icon.Children.Add($glyph)
    $null = $icon.Children.Add($spinner)
    $null = $content.Children.Add($icon)

    $text = New-Object System.Windows.Controls.StackPanel
    $text.VerticalAlignment = "Center"
    [System.Windows.Controls.Grid]::SetColumn($text, 2)
    $label = New-Object System.Windows.Controls.TextBlock
    $label.Text = [string]$Check.Name
    $label.FontWeight = "SemiBold"
    $label.TextTrimming = "CharacterEllipsis"
    $label.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushInk")
    $result = New-Object System.Windows.Controls.TextBlock
    $result.Text = (Get-WinToolText "msg.waiting") + (Get-WinToolHomeEllipsis)
    $result.TextTrimming = "CharacterEllipsis"
    $result.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushMuted")
    $null = $text.Children.Add($label)
    $null = $text.Children.Add($result)
    $null = $content.Children.Add($text)

    $button = New-Object System.Windows.Controls.Button
    $button.Style = $script:WinToolWindow.FindResource("HomeRowButton")
    $button.Content = "Fix"
    $button.VerticalAlignment = "Center"
    $button.IsEnabled = $false
    [System.Windows.Controls.Grid]::SetColumn($button, 4)
    $null = $grid.Children.Add($button)

    $row = [pscustomobject]@{
        Id = [string]$Check.Id
        Name = [string]$Check.Name
        Border = $border
        Content = $content
        Disc = $disc
        Glyph = $glyph
        Spinner = $spinner
        Label = $label
        Result = $result
        Button = $button
        Status = "busy"
    }
    Register-WinToolUiEvent -Control $button -EventName "Click" -Name ("Home: " + [string]$Check.Name) -Data ([string]$Check.Id) -Action {
        param($source, $eventData, $checkId)
        $null = $source, $eventData
        Invoke-WinToolHomeAction -Id $checkId
    }
    return $row
}

function Set-WinToolHomeRow {
    # Shows one state in a row's fixed slots. Action "none" hides the button
    # but keeps its slot; "off" shows it greyed out.
    param(
        [Parameter(Mandatory = $true)]$Row,
        [Parameter(Mandatory = $true)][ValidateSet("busy", "ok", "warn", "bad", "unknown")][string]$Status,
        [Parameter(Mandatory = $true)][string]$Text,
        [ValidateSet("fix", "review", "none", "off")][string]$Action = "none",
        [switch]$Fade
    )
    $Row.Status = $Status
    $Row.Result.Text = $Text
    $rotate = $Row.Spinner.RenderTransform
    if ($Status -eq "busy") {
        $Row.Border.ToolTip = $null
        $Row.Disc.Fill = [System.Windows.Media.Brushes]::Transparent
        $Row.Glyph.Visibility = "Hidden"
        $Row.Spinner.Visibility = "Visible"
        if (-not (Test-WinToolHomeReduceMotion)) {
            $spin = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 360, [System.Windows.Duration]::new([TimeSpan]::FromSeconds(1)))
            $spin.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $spin)
        }
    }
    else {
        $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
        $Row.Spinner.Visibility = "Hidden"
        $Row.Glyph.Visibility = "Visible"
        $look = switch ($Status) {
            "ok" { @{ Soft = "BrushOkSoft"; Ink = "BrushOk"; Data = "M 7,11.5 L 10,14.5 L 15.5,8" } }
            "warn" { @{ Soft = "BrushWarnSoft"; Ink = "BrushWarn"; Data = "M 11,6.5 L 11,12 M 11,15.5 L 11,15.6" } }
            "bad" { @{ Soft = "BrushBadSoft"; Ink = "BrushBad"; Data = "M 8,8 L 14,14 M 14,8 L 8,14" } }
            default { @{ Soft = "BrushNavHover"; Ink = "BrushMuted"; Data = "M 11,10 L 11,15.5 M 11,6.5 L 11,6.6" } }
        }
        $Row.Disc.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, $look.Soft)
        $Row.Glyph.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, $look.Ink)
        $Row.Glyph.Data = [System.Windows.Media.Geometry]::Parse($look.Data)
    }
    $button = $Row.Button
    switch ($Action) {
        "fix" {
            $button.Content = Get-WinToolText "button.fix"
            $button.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty, "BrushAccentSoft")
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushAccent")
            $button.Visibility = "Visible"
            $button.IsEnabled = $true
        }
        "review" {
            $button.Content = Get-WinToolText "button.review"
            $button.Background = [System.Windows.Media.Brushes]::Transparent
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushLine")
            $button.Visibility = "Visible"
            $button.IsEnabled = $true
        }
        "off" {
            $button.Content = Get-WinToolText "button.fix"
            $button.Background = [System.Windows.Media.Brushes]::Transparent
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushLine")
            $button.Visibility = "Visible"
            $button.IsEnabled = $false
        }
        default {
            $button.Visibility = "Hidden"
            $button.IsEnabled = $false
        }
    }
    if ($Fade -and -not (Test-WinToolHomeReduceMotion)) {
        $animation = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 1, [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(320)))
        $Row.Content.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animation)
    }
}

function New-WinToolHomeMini {
    param(
        [Parameter(Mandatory = $true)][string]$Key,
        [Parameter(Mandatory = $true)][string]$Title,
        [int]$Column,
        [string]$From,
        [string]$To,
        [string]$Line
    )
    $card = New-Object System.Windows.Controls.Border
    $card.CornerRadius = [System.Windows.CornerRadius]::new(16)
    $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.Padding = [System.Windows.Thickness]::new(16, 14, 16, 12)
    $card.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushCard")
    $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    [System.Windows.Controls.Grid]::SetColumn($card, $Column)
    $grid = New-Object System.Windows.Controls.Grid
    $grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }))
    $grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::new(98) }))
    $titleHeight = New-Object System.Windows.Controls.RowDefinition
    $titleHeight.Height = [System.Windows.GridLength]::Auto
    $titleHeight.MinHeight = 30
    $grid.RowDefinitions.Add($titleHeight)
    foreach ($height in @(32, 32)) {
        $grid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height = [System.Windows.GridLength]::new($height) }))
    }
    $card.Child = $grid

    $titleRow = New-Object System.Windows.Controls.StackPanel
    $titleRow.Orientation = "Vertical"
    $null = $grid.Children.Add($titleRow)
    $titleText = New-Object System.Windows.Controls.TextBlock
    $titleText.Text = $Title
    $titleText.FontWeight = "SemiBold"
    $titleText.VerticalAlignment = "Center"
    $titleText.TextWrapping = "NoWrap"
    $titleText.TextTrimming = "CharacterEllipsis"
    $titleText.ToolTip = $Title
    $titleText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushMuted")
    $null = $titleRow.Children.Add($titleText)

    $tag = New-Object System.Windows.Controls.Border
    $tag.MinHeight = 22
    $tag.CornerRadius = [System.Windows.CornerRadius]::new(11)
    $tag.Padding = [System.Windows.Thickness]::new(8, 2, 8, 2)
    $tag.HorizontalAlignment = "Left"
    $tag.VerticalAlignment = "Center"
    $tag.Margin = [System.Windows.Thickness]::new(0, 4, 8, 0)
    $tagText = New-Object System.Windows.Controls.TextBlock
    $tagText.FontWeight = "SemiBold"
    $tagText.HorizontalAlignment = "Center"
    $tagText.VerticalAlignment = "Center"
    $tagText.Text = Get-WinToolText "msg.reading"
    $tag.Child = $tagText
    $null = $titleRow.Children.Add($tag)

    $value = New-Object System.Windows.Controls.TextBlock
    $value.FontWeight = "Bold"
    $value.VerticalAlignment = "Center"
    $value.TextTrimming = "CharacterEllipsis"
    $value.Text = (Get-WinToolText "msg.reading") + (Get-WinToolHomeEllipsis)
    $value.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushInk")
    [System.Windows.Controls.Grid]::SetRow($value, 1)
    $null = $grid.Children.Add($value)
    $detail = New-Object System.Windows.Controls.TextBlock
    $detail.VerticalAlignment = "Center"
    $detail.TextTrimming = "CharacterEllipsis"
    $detail.Text = " "
    $detail.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushMuted")
    [System.Windows.Controls.Grid]::SetRow($detail, 2)
    $null = $grid.Children.Add($detail)

    $ring = New-Object System.Windows.Controls.Canvas
    $ring.Width = 86
    $ring.Height = 86
    $ring.HorizontalAlignment = "Right"
    $ring.VerticalAlignment = "Center"
    [System.Windows.Controls.Grid]::SetColumn($ring, 1)
    [System.Windows.Controls.Grid]::SetRow($ring, 0)
    [System.Windows.Controls.Grid]::SetRowSpan($ring, 3)
    $track = New-Object System.Windows.Shapes.Ellipse
    $track.Width = 64
    $track.Height = 64
    $track.StrokeThickness = 8
    $track.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, "BrushProgressTrack")
    [System.Windows.Controls.Canvas]::SetLeft($track, 11)
    [System.Windows.Controls.Canvas]::SetTop($track, 11)
    $arc = New-Object System.Windows.Shapes.Path
    $arc.StrokeThickness = 8
    $arc.StrokeStartLineCap = "Round"
    $arc.StrokeEndLineCap = "Round"
    $arc.Stroke = New-WinToolHomeBrush -From $From -To $To
    $arc.Visibility = "Hidden"
    $null = $ring.Children.Add($track)
    $null = $ring.Children.Add($arc)
    $null = $grid.Children.Add($ring)

    # The live trace stays in the tree at a fixed empty size. The approved card shows the ring.
    $spark = New-Object System.Windows.Controls.Grid
    $spark.Width = 0
    $spark.Height = 0
    $spark.Visibility = "Collapsed"
    $spark.IsHitTestVisible = $false
    $fill = New-Object System.Windows.Shapes.Path
    $fill.Fill = New-WinToolHomeBrush -From $Line -To $Line -Vertical -Alpha 0.28
    $stroke = New-Object System.Windows.Shapes.Path
    $stroke.StrokeThickness = 1.6
    $stroke.StrokeLineJoin = "Round"
    $stroke.Stroke = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($Line))
    $null = $spark.Children.Add($fill)
    $null = $spark.Children.Add($stroke)
    $null = $grid.Children.Add($spark)

    $mini = [pscustomobject]@{
        Key = $Key
        Card = $card
        TitleText = $titleText
        Arc = $arc
        Tag = $tag
        TagText = $tagText
        Value = $value
        Detail = $detail
        Spark = $spark
        SparkFill = $fill
        SparkLine = $stroke
        Points = (New-Object System.Collections.Generic.List[double])
    }
    Register-WinToolUiEvent -Control $spark -EventName "SizeChanged" -Name ("Home card " + $Key) -Data $mini -Action {
        param($source, $eventData, $card)
        $null = $source, $eventData
        Update-WinToolHomeSpark -Mini $card
    }
    return $mini
}

function Set-WinToolHomeMiniTag {
    param($Mini, [string]$Text, [ValidateSet("ok", "warn", "bad", "neutral")][string]$Tone)
    $Mini.TagText.Text = $Text
    $look = switch ($Tone) {
        "ok" { @("BrushOkSoft", "BrushOk") }
        "warn" { @("BrushWarnSoft", "BrushWarn") }
        "bad" { @("BrushBadSoft", "BrushBad") }
        default { @("BrushNavHover", "BrushMuted") }
    }
    $Mini.Tag.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $look[0])
    $Mini.TagText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $look[1])
}

function Set-WinToolHomeMiniRing {
    param($Mini, [double]$Fraction)
    if ($Fraction -le 0) {
        $Mini.Arc.Visibility = "Hidden"
        return
    }
    $angle = [Math]::Min(1.0, $Fraction) * 360
    $shape = Get-WinToolHomeArcData -CenterX 43 -CenterY 43 -Radius 32 -Angle $angle
    $Mini.Arc.Data = [System.Windows.Media.Geometry]::Parse($shape.Data)
    $Mini.Arc.Visibility = "Visible"
}

function Add-WinToolHomeSparkPoint {
    param($Mini, [double]$Value)
    if ($Value -lt 0) { return }
    $Mini.Points.Add([Math]::Max(0, [Math]::Min(100, $Value)))
    while ($Mini.Points.Count -gt 24) { $Mini.Points.RemoveAt(0) }
    Update-WinToolHomeSpark -Mini $Mini
}

function Update-WinToolHomeSpark {
    # The newest sample sits on the right; 24 samples fill the width.
    param($Mini)
    $width = [double]$Mini.Spark.ActualWidth
    $height = [double]$Mini.Spark.ActualHeight
    $count = $Mini.Points.Count
    if ($width -le 0 -or $height -le 0 -or $count -lt 1) {
        $Mini.SparkLine.Data = $null
        $Mini.SparkFill.Data = $null
        return
    }
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    $step = $width / 23
    $points = New-Object System.Collections.Generic.List[string]
    $firstX = 0
    if ($count -eq 1) {
        $firstX = [Math]::Max(0, $width - $step)
        $y = ($height - 2) - ($Mini.Points[0] / 100) * ($height - 8)
        $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $firstX, $y))
        $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $width, $y))
    }
    else {
        for ($i = 0; $i -lt $count; $i++) {
            $x = $width - ($count - 1 - $i) * $step
            if ($i -eq 0) { $firstX = $x }
            $y = ($height - 2) - ($Mini.Points[$i] / 100) * ($height - 8)
            $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $x, $y))
        }
    }
    $line = "M " + ($points -join " L ")
    $Mini.SparkLine.Data = [System.Windows.Media.Geometry]::Parse($line)
    $Mini.SparkFill.Data = [System.Windows.Media.Geometry]::Parse(($line + [string]::Format($culture, " L {0:0.##},{2:0.##} L {1:0.##},{2:0.##} Z", $width, $firstX, $height)))
}

function Format-WinToolHomeSize {
    # Installed sizes read best rounded: 32 GB of memory, 512 GB disk.
    param([double]$Bytes, [switch]$Decimal)
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    if ($Decimal) {
        $gb = $Bytes / 1e9
        if ($gb -ge 1000) { return [string]::Format($culture, "{0:0.#} TB", $gb / 1000) }
        return [string]::Format($culture, "{0:0} GB", $gb)
    }
    $gib = $Bytes / 1GB
    if ([Math]::Abs($gib - [Math]::Round($gib)) -lt 0.06) { return [string]::Format($culture, "{0:0} GB", $gib) }
    return [string]::Format($culture, "{0:0.0} GB", $gib)
}

function Update-WinToolHomeCard {
    # Fills the three cards from the static PC info and the latest sample.
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $null -eq $hs.Minis -or $null -eq $hs.Minis["memory"]) { return }
    $dot = " " + [string][char]0x00B7 + " "
    $info = $hs.Info
    $sample = $hs.LastSample
    $memory = $hs.Minis["memory"]
    $disk = $hs.Minis["disk"]
    $pc = $hs.Minis["pc"]
    if ($null -ne $sample -and [double]$sample.MemoryTotal -gt 0) {
        $fraction = [double]$sample.MemoryUsed / [double]$sample.MemoryTotal
        Set-WinToolHomeMiniRing -Mini $memory -Fraction $fraction
        Set-WinToolHomeMiniTag -Mini $memory -Text ((Get-WinToolText "msg.percent-used") -f ($fraction * 100)) -Tone "neutral"
        $memory.Value.Text = (Get-WinToolText "msg.n-in-use" (Format-WinToolByteSize -Bytes ([double]$sample.MemoryUsed)))
        $total = [double]$sample.MemoryTotal
        $kind = ""
        if ($null -ne $info) {
            if ([double]$info.MemoryTotal -gt 0) { $total = [double]$info.MemoryTotal }
            $kind = Get-WinToolMemoryTypeName -Code ([int]$info.MemoryType)
        }
        $text = (Get-WinToolText "msg.n-total" (Format-WinToolHomeSize -Bytes $total))
        if (-not [string]::IsNullOrWhiteSpace($kind)) { $text += $dot + $kind }
        $memory.Detail.Text = $text
        $memory.Card.ToolTip = ((Get-WinToolText "msg.memory-n-n") -f $memory.Value.Text, $memory.Detail.Text)
    }
    if ($null -ne $sample -and [double]$sample.DiskTotal -gt 0) {
        $free = [double]$sample.DiskFree / [double]$sample.DiskTotal
        Set-WinToolHomeMiniRing -Mini $disk -Fraction (1 - $free)
        Set-WinToolHomeMiniTag -Mini $disk -Text ((Get-WinToolText "msg.percent-free") -f ($free * 100)) -Tone (Get-WinToolHomeDiskTone -FreePercent ($free * 100))
        $disk.Value.Text = (Get-WinToolText "msg.n-free" (Format-WinToolByteSize -Bytes ([double]$sample.DiskFree)))
        $size = [double]$sample.DiskTotal
        $media = ""
        if ($null -ne $info) {
            if ([double]$info.DiskSize -gt 0) { $size = [double]$info.DiskSize }
            if (@("SSD", "HDD") -contains [string]$info.DiskMedia) { $media = " " + [string]$info.DiskMedia }
        }
        $letter = ([string]$env:SystemDrive)
        if ([string]::IsNullOrWhiteSpace($letter)) { $letter = "C:" }
        $disk.Detail.Text = (Format-WinToolHomeSize -Bytes $size -Decimal) + $media + $dot + (Get-WinToolText "msg.drive-n" $letter)
        $disk.Card.ToolTip = ((Get-WinToolText "msg.windows-disk-n-n") -f $disk.Value.Text, $disk.Detail.Text)
    }
    if ($null -ne $info) {
        Set-WinToolHomeMiniRing -Mini $pc -Fraction 1
        if (-not [string]::IsNullOrWhiteSpace([string]$info.Os)) { $pc.Value.Text = [string]$info.Os }
        $parts = @()
        if (-not [string]::IsNullOrWhiteSpace([string]$info.Version)) { $parts += [string]$info.Version }
        $cpu = Format-WinToolCpuName -Name ([string]$info.Cpu)
        if (-not [string]::IsNullOrWhiteSpace($cpu)) { $parts += $cpu }
        if ($parts.Count -gt 0) { $pc.Detail.Text = ($parts -join $dot) }
    }
    $driver = $hs.Results["drivers"]
    $diskHealth = $hs.Results["disk"]
    if ($hs.Phase -eq "analyzing" -or $null -eq $driver -or $null -eq $diskHealth) {
        Set-WinToolHomeMiniTag -Mini $pc -Text (Get-WinToolText "msg.checking") -Tone "neutral"
        $pc.Card.ToolTip = (Get-WinToolText "msg.checking-device-drivers-and-drive-health")
    }
    elseif ($driver.Status -eq "bad" -and $diskHealth.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text (Get-WinToolCountText "msg.n-issues" 2) -Tone "warn"
        $pc.Card.ToolTip = ((Get-WinToolText "msg.drivers-n-disk-health-n") -f $driver.Text, $diskHealth.Text)
    }
    elseif ($driver.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text (Get-WinToolText "msg.driver-issue") -Tone "warn"
        $tip = (Get-WinToolText "msg.drivers-colon-n" $driver.Text)
        if (@($driver.Detail).Count -gt 0) { $tip += "`n" + ((@($driver.Detail | Select-Object -First 5)) -join "`n") }
        $pc.Card.ToolTip = $tip
    }
    elseif ($diskHealth.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text (Get-WinToolText "msg.disk-issue") -Tone "bad"
        $tip = (Get-WinToolText "msg.disk-health-colon-n" $diskHealth.Text)
        if (@($diskHealth.Detail).Count -gt 0) { $tip += "`n" + ((@($diskHealth.Detail | Select-Object -First 5)) -join "`n") }
        $pc.Card.ToolTip = $tip
    }
    else {
        Set-WinToolHomeMiniTag -Mini $pc -Text (Get-WinToolText "msg.healthy") -Tone "ok"
        $pc.Card.ToolTip = (Get-WinToolText "msg.device-drivers-and-drive-health-report-no-problems")
    }
}

function Add-WinToolHomeSample {
    param([Parameter(Mandatory = $true)]$Sample)
    $hs = $script:WinToolState.Home
    $hs.LastSample = $Sample
    if ([double]$Sample.MemoryTotal -gt 0) {
        Add-WinToolHomeSparkPoint -Mini $hs.Minis["memory"] -Value (100 * [double]$Sample.MemoryUsed / [double]$Sample.MemoryTotal)
    }
    Add-WinToolHomeSparkPoint -Mini $hs.Minis["disk"] -Value ([double]$Sample.DiskBusy)
    Add-WinToolHomeSparkPoint -Mini $hs.Minis["pc"] -Value ([double]$Sample.Cpu)
    Update-WinToolHomeCard
}

function Initialize-WinToolHomeView {
    param([switch]$DeferChrome)
    $script:WinToolState.Home = @{
        Phase = "idle"
        Results = @{}
        Rows = @{}
        Minis = @{}
        Pending = @{}
        Started = $null
        Finished = $null
        Seconds = 0
        Score = $null
        Arc = 0.0
        ArcTarget = 0.0
        AnimStart = [DateTime]::Now
        Info = $null
        LastSample = $null
        WaitTweaks = $false
        Previous = $null
    }
    $hs = $script:WinToolState.Home
    $hs.ChromeQueue = New-Object System.Collections.Generic.Queue[object]
    $checks = @(Get-WinToolHomeCheckList)
    for ($i = 0; $i -lt $checks.Count; $i++) {
        $hs.ChromeQueue.Enqueue(@{
                Kind = "row"
                Check = $checks[$i]
                Last = ($i -eq $checks.Count - 1)
            })
    }
    foreach ($mini in @(
            @{ Kind = "mini"; Key = "memory"; TitleKey = "msg.memory"; Column = 0; From = "#4C8DFF"; To = "#8B5CF6"; Line = "#8B7CF6" }
            @{ Kind = "mini"; Key = "disk"; TitleKey = "msg.windows-disk"; Column = 2; From = "#F5B942"; To = "#F07178"; Line = "#F5A742" }
            @{ Kind = "mini"; Key = "pc"; TitleKey = "drivers.pcLabel"; Column = 4; From = "#3DD68C"; To = "#4C8DFF"; Line = "#4C8DFF" }
        )) {
        $hs.ChromeQueue.Enqueue($mini)
    }

    $history = @(Read-WinToolHomeHistory)
    if ($history.Count -gt 0) { $hs.Previous = $history[-1] }
    (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
    Set-WinToolHomeArc -Angle 0
    Sync-WinToolHomeHeader

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeAgain") -EventName "Click" -Name "Analyze again" -Action {
        Start-WinToolHomeAnalysis
    }
        Add-WinToolAdminBadgeNear -Name "HomeFixAll" -Place "Before" | Out-Null
Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeFixAll") -EventName "Click" -Name "Fix all" -Action {
        Invoke-WinToolHomeFixAll
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeHistoryLink") -EventName "Click" -Name "View history" -Action {
        Show-WinToolHomeHistory
    }
    # Timer, sampler, and analysis start after the first frame so they do not
    # block the dispatcher during Loaded.
    if (-not $DeferChrome) {
        while ($null -ne $hs.ChromeQueue -and $hs.ChromeQueue.Count -gt 0) {
            Add-WinToolHomeChromeStep
        }
    }
}

function Sync-WinToolHomeHeader {
    $hs = $script:WinToolState.Home
    $done = @($hs.Results.Values).Count
    $total = @(Get-WinToolHomeCheckList).Count
    $busyRing = Get-WinToolUi -Name "HomeRingBusy"
    $doneRing = Get-WinToolUi -Name "HomeRingDone"
    $fixAll = Get-WinToolUi -Name "HomeFixAll"
    $again = Get-WinToolUi -Name "HomeAgain"
    $headline = Get-WinToolUi -Name "HomeHeadline"
    $lead = Get-WinToolUi -Name "HomeLead"
    $count = Get-WinToolUi -Name "HomeCheckCount"
    (Get-WinToolUi -Name "HomeRingProgress").Text = (Get-WinToolText "msg.n-of-n-checks") -f $done, $total
    switch ($hs.Phase) {
        "done" {
            $results = @($hs.Results.Values)
            $score = $hs.Score
            if ($null -eq $score) { $score = Get-WinToolHomeScore -Result $results }
            $verdict = Get-WinToolHomeVerdict -Score $score
            $fixable = @($results | Where-Object { $_.Fixable }).Count
            $busyRing.Visibility = "Collapsed"
            $doneRing.Visibility = "Visible"
            (Get-WinToolUi -Name "HomeScore").Text = [string]$score
            (Get-WinToolUi -Name "HomeVerdictText").Text = $verdict.Text
            $tone = @{ ok = @("BrushOkSoft", "BrushOk"); warn = @("BrushWarnSoft", "BrushWarn"); bad = @("BrushBadSoft", "BrushBad") }[$verdict.Tone]
            (Get-WinToolUi -Name "HomeVerdict").SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $tone[0])
            (Get-WinToolUi -Name "HomeVerdictText").SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $tone[1])
            $headline.Text = (Get-WinToolText "msg.analysis-complete")
            $lead.Text = Get-WinToolHomeLead -Result $results
            $count.Text = (Get-WinToolText "msg.n-of-n-can-be-fixed") -f $fixable, $total
            $fixAll.IsEnabled = ($fixable -gt 0)
            $again.IsEnabled = $true
            $hs.ArcTarget = 360.0 * $score / 100
        }
        "fixing" {
            $busyRing.Visibility = "Collapsed"
            $doneRing.Visibility = "Visible"
            $headline.Text = (Get-WinToolText "msg.fixing") + (Get-WinToolHomeEllipsis)
            $lead.Text = (Get-WinToolText "msg.only-safe-changes-are-made-you-can-keep-using-your-pc")
            $count.Text = (Get-WinToolText "msg.n-of-n-complete") -f $done, $total
            $fixAll.IsEnabled = $false
            $again.IsEnabled = $false
        }
        default {
            $busyRing.Visibility = "Visible"
            $doneRing.Visibility = "Collapsed"
            $headline.Text = (Get-WinToolText "msg.analyzing-your-pc") + (Get-WinToolHomeEllipsis)
            $lead.Text = (Get-WinToolText "ui.HomeLead.Text")
            $count.Text = (Get-WinToolText "msg.n-of-n-complete") -f $done, $total
            $fixAll.IsEnabled = $false
            $again.IsEnabled = ($hs.Phase -eq "idle")
        }
    }
    Sync-WinToolHomeRunText
}

function Sync-WinToolHomeRunText {
    $hs = $script:WinToolState.Home
    $text = Get-WinToolUi -Name "HomeRunText"
    if ($null -eq $hs.Started) {
        $text.Text = " "
        return
    }
    switch ($hs.Phase) {
        "analyzing" { $text.Text = (Get-WinToolText "msg.running-for-ns") -f [int]([DateTime]::Now - [datetime]$hs.Started).TotalSeconds }
        "fixing" { $text.Text = (Get-WinToolText "msg.fixing") + (Get-WinToolHomeEllipsis) }
        default { $text.Text = (Get-WinToolText "msg.finished-in-ns") -f [int]$hs.Seconds }
    }
}

function Start-WinToolHomeTimer {
    if ($null -ne $script:WinToolState.HomeTimer) { return }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(250)
    Register-WinToolUiEvent -Control $timer -EventName "Tick" -Name "Home refresh" -Action { Update-WinToolHomePoll }
    $timer.Start()
    $script:WinToolState.HomeTimer = $timer
    $animation = New-Object System.Windows.Threading.DispatcherTimer
    $animation.Interval = [TimeSpan]::FromMilliseconds(16)
    Register-WinToolUiEvent -Control $animation -EventName "Tick" -Name "Home ring" -Action { Update-WinToolHomeAnimation }
    $script:WinToolState.HomeAnimTimer = $animation
}

function Start-WinToolHomeAnimation {
    if ((Test-WinToolHomeReduceMotion) -or $null -eq $script:WinToolState.HomeAnimTimer) {
        $hs = $script:WinToolState.Home
        if ($hs.Phase -eq "analyzing") {
            $done = @($hs.Results.Values).Count
            Set-WinToolHomeArc -Angle ([Math]::Max(24, 360.0 * $done / 5 * 0.9))
        }
        else {
            Set-WinToolHomeArc -Angle $hs.ArcTarget
        }
        return
    }
    $script:WinToolState.HomeAnimTimer.Start()
}

function Update-WinToolHomeAnimation {
    # While analyzing the arc grows and shrinks; afterwards it eases to the score.
    $hs = $script:WinToolState.Home
    if ($hs.Phase -eq "analyzing") {
        $t = ([DateTime]::Now - [datetime]$hs.AnimStart).TotalSeconds
        $wave = 0.5 - 0.5 * [Math]::Cos(2 * [Math]::PI * $t / 2.4)
        Set-WinToolHomeArc -Angle (50 + 260 * $wave)
        return
    }
    $diff = [double]$hs.ArcTarget - [double]$hs.Arc
    if ([Math]::Abs($diff) -lt 0.4) {
        Set-WinToolHomeArc -Angle $hs.ArcTarget
        $script:WinToolState.HomeAnimTimer.Stop()
        return
    }
    # About 600 ms to draw the ring in (1 - 0.92^38 frames at 16 ms).
    Set-WinToolHomeArc -Angle ([double]$hs.Arc + $diff * 0.08)
}

function Start-WinToolHomeCheck {
    # Starts one check in its own runspace. Tests set WinToolHomeNoJobs and
    # feed the results through Complete-WinToolHomeCheck.
    param([Parameter(Mandatory = $true)][string]$Id)
    $hs = $script:WinToolState.Home
    $hs.Pending[$Id] = $true
    $hs.Results.Remove($Id)
    $row = $hs.Rows[$Id]
    if ($null -ne $row) {
        Set-WinToolHomeRow -Row $row -Status "busy" -Text (Get-WinToolText "msg.checking-ellipsis") -Action "off"
    }
    if ($script:WinToolHomeNoJobs) { return }
    $key = "HomeJob_" + $Id
    Stop-WinToolThread -Job $script:WinToolState[$key]
    try {
        $scriptText = Get-WinToolHomeCheckScript -Id $Id
        switch ($Id) {
            "junk" { $job = Start-WinToolHomeJob -ScriptText $scriptText -Argument @(, @(Get-WinToolHomeJunkLocation)) }
            "tweaks" {
                $recommended = @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended")
                $job = Start-WinToolHomeJob -ScriptText $scriptText -Argument @(, $recommended) -WithWinTool
            }
            default { $job = Start-WinToolHomeJob -ScriptText $scriptText }
        }
        $script:WinToolState[$key] = $job
    }
    catch {
        Complete-WinToolHomeCheck -Id $Id -ErrorMessage $_.Exception.Message
    }
}

function Sync-WinToolHomeCurrentScore {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -ne "done") { return }
    $results = @($hs.Results.Values)
    if ($results.Count -lt @(Get-WinToolHomeCheckList).Count) { return }
    $score = Get-WinToolHomeScore -Result $results
    $hs.Score = $score
    if ($null -ne $hs.Finished) {
        $hs.Previous = [pscustomobject]@{ Time = $hs.Finished; Score = $score; Seconds = $hs.Seconds }
        (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
        if (-not $script:WinToolHomeNoJobs) {
            Set-WinToolHomeLatestHistory -Score $score
        }
    }
    Sync-WinToolHomeHeader
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
}

function Sync-WinToolHomeTweakRow {
    # Updates the Home tweaks check from the Tweaks page rows when the analysis
    # has already finished, so toggling switches keeps Home's score in sync.
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -ne "done" -or $hs.WaitTweaks) { return }
    if (-not $script:WinToolState.TweakStateRead) { return }
    $byId = @{}
    foreach ($row in @($script:WinToolState.TweakRows)) {
        $byId[[string]$row.Id] = $row
    }
    $data = foreach ($tweak in @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended")) {
        $id = [string]$tweak.id
        $state = "unknown"
        if ($byId.ContainsKey($id)) {
            $tweakRow = $byId[$id]
            if ($tweakRow.Checkbox.IsChecked -eq $true) { $state = "on" }
            elseif ($tweakRow.State -eq "off" -or $tweakRow.Checkbox.IsChecked -eq $false) { $state = "off" }
        }
        [pscustomobject]@{ Id = $id; Name = [string]$tweak.name; State = $state }
    }
    Complete-WinToolHomeCheck -Id "tweaks" -Data @($data)
}

function Complete-WinToolHomeCheck {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Data,
        [string]$ErrorMessage,
        [switch]$Partial
    )
    $hs = $script:WinToolState.Home
    $result = ConvertTo-WinToolHomeResult -Id $Id -Data $Data -ErrorMessage $ErrorMessage
    if ($Partial -and -not [string]::IsNullOrWhiteSpace([string]$result.Text)) {
        $result.Text = (Get-WinToolText "msg.junk-scan-partial" $result.Text)
        if ($result.Status -eq "ok") { $result.Status = "warn" }
    }
    $hs.Results[$Id] = $result
    $hs.Pending.Remove($Id)
    $action = [string]$result.Action
    $row = $hs.Rows[$Id]
    Set-WinToolHomeRow -Row $row -Status $result.Status -Text $result.Text -Action $action -Fade
    $tipLines = @($result.Name + ": " + $result.Text)
    if (@($result.Detail).Count -gt 0) {
        $tipLines += @($result.Detail | Select-Object -First 10 | ForEach-Object { "- " + $_ })
        if (@($result.Detail).Count -gt 10) { $tipLines += "- ..." }
    }
    $row.Border.ToolTip = ($tipLines -join "`n")
    if ($result.Status -eq "unknown" -and @($result.Detail).Count -gt 0) {
        Write-WinToolLog -Message ((Get-WinToolText "msg.home-n-could-not-be-checked-n") -f $result.Name, (@($result.Detail) -join " ")) -Level "warn" -Diagnostic
    }
    if ($hs.Phase -eq "analyzing") {
        Sync-WinToolHomeHeader
        if ($hs.Pending.Count -eq 0) { Complete-WinToolHomeAnalysis }
        elseif (Test-WinToolHomeReduceMotion) { Start-WinToolHomeAnimation }
        return
    }
    if ($hs.Phase -eq "fixing") {
        Test-WinToolHomeFixDone
        return
    }
    Sync-WinToolHomeCurrentScore
}

function Add-WinToolHomeChromeStep {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $null -eq $hs.ChromeQueue) { return }
    $added = 0
    while ($hs.ChromeQueue.Count -gt 0 -and $added -lt 2) {
        $item = $hs.ChromeQueue.Dequeue()
        $kind = [string]$item.Kind
        if ($kind -eq "row") {
            $checkHost = Get-WinToolUi -Name "HomeChecks"
            $row = New-WinToolHomeRow -Check $item.Check -Last ([bool]$item.Last)
            $hs.Rows[$row.Id] = $row
            $null = $checkHost.Children.Add($row.Border)
            Set-WinToolHomeRow -Row $row -Status "busy" -Text (Get-WinToolText "msg.checking-ellipsis") -Action "off"
        }
        elseif ($kind -eq "mini") {
            $minis = Get-WinToolUi -Name "HomeMinis"
            $hs.Minis[$item.Key] = New-WinToolHomeMini -Key $item.Key -Title (Get-WinToolText $item.TitleKey) -Column $item.Column -From $item.From -To $item.To -Line $item.Line
            $null = $minis.Children.Add($hs.Minis[$item.Key].Card)
        }
        $added++
    }
    if ($hs.ChromeQueue.Count -eq 0) {
        $hs.ChromeQueue = $null
        Update-WinToolHomeCard
    }
}

function Start-WinToolHomeAnalysis {
    param(
        [switch]$DeferTweaks,
        [switch]$Stagger
    )
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -eq "analyzing" -or $hs.Phase -eq "fixing") { return }
    $hs.Phase = "analyzing"
    $hs.Results = @{}
    $hs.Pending = @{}
    $hs.Score = $null
    $hs.Started = [DateTime]::Now
    $hs.AnimStart = [DateTime]::Now
    Sync-WinToolHomeHeader
    $ids = @()
    foreach ($check in @(Get-WinToolHomeCheckList)) {
        if ($DeferTweaks -and $check.Id -eq "tweaks") { continue }
        $ids += [string]$check.Id
    }
    if ($Stagger) {
        $script:WinToolHomeStaggerIds = @($ids)
    }
    else {
        foreach ($id in $ids) {
            Start-WinToolHomeCheck -Id $id
        }
    }
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
    if ($hs.Phase -eq "analyzing" -and $hs.Pending.Count -eq 0 -and -not $Stagger) { Complete-WinToolHomeAnalysis }
}

function Start-WinToolHomeTweakCheck {
    if ($script:WinToolShuttingDown) { return }
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -ne "analyzing") { return }
    if ($hs.Pending.ContainsKey("tweaks") -or $hs.Results.ContainsKey("tweaks")) { return }
    Start-WinToolHomeCheck -Id "tweaks"
}

function Complete-WinToolHomeAnalysis {
    $hs = $script:WinToolState.Home
    $hs.Phase = "done"
    $hs.Finished = [DateTime]::Now
    $hs.Seconds = [int][Math]::Max(1, ([datetime]$hs.Finished - [datetime]$hs.Started).TotalSeconds)
    $results = @($hs.Results.Values)
    $score = Get-WinToolHomeScore -Result $results
    $hs.Score = $score
    if (-not $script:WinToolHomeNoJobs) {
        Add-WinToolHomeHistory -Time $hs.Finished -Score $score -Seconds $hs.Seconds
    }
    $hs.Previous = [pscustomobject]@{ Time = $hs.Finished; Score = $score; Seconds = $hs.Seconds }
    (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
    Sync-WinToolHomeHeader
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
    Write-WinToolLog -Message ((Get-WinToolText "msg.home-analysis-finished-in-ns-score-n") -f $hs.Seconds, $score) -Level "info" -Diagnostic
}

function Start-WinToolHomeInfo {
    if ($script:WinToolHomeNoJobs -or $null -ne $script:WinToolState.HomeInfoJob) { return }
    $script:WinToolState.HomeInfoJob = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "info")
}

function Start-WinToolHomeSampler {
    if ($script:WinToolHomeNoJobs) { return }
    Start-WinToolHomeInfo
    if ($null -ne $script:WinToolState.HomeSampler) { return }
    $script:WinToolState.HomeSampler = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "sampler")
}

function Update-WinToolHomePoll {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs) { return }
    foreach ($check in @(Get-WinToolHomeCheckList)) {
        $key = "HomeJob_" + $check.Id
        $job = $script:WinToolState[$key]
        if ($null -eq $job -or -not $job.Sync.Done) { continue }
        $data = $job.Sync.Data
        $errorText = [string]$job.Sync.Error
        $partial = $false
        try { $partial = [bool]$job.Sync.Partial } catch { $partial = $false }
        Stop-WinToolThread -Job $job
        $script:WinToolState[$key] = $null
        Complete-WinToolHomeCheck -Id $check.Id -Data $data -ErrorMessage $errorText -Partial:$partial
        break
    }
    $clean = $script:WinToolState.HomeCleanJob
    if ($null -ne $clean -and $clean.Sync.Done) {
        $freed = [double]$clean.Sync.Data
        $errorText = [string]$clean.Sync.Error
        Stop-WinToolThread -Job $clean
        $script:WinToolState.HomeCleanJob = $null
        if ([string]::IsNullOrWhiteSpace($errorText)) {
            Write-WinToolLog -Message ((Get-WinToolText "msg.junk-files-freed-n-files-in-use-were-skipped") -f (Format-WinToolByteSize -Bytes $freed)) -Level "ok"
        }
        else {
            Write-WinToolLog -Message ((Get-WinToolText "msg.junk-files-cleaning-stopped-n") -f $errorText) -Level "warn"
        }
        Start-WinToolHomeCheck -Id "junk"
    }
    if ($hs.WaitTweaks -and $null -eq $script:WinToolState.TweakQueue -and $null -eq $script:WinToolState.RestoreJob -and -not $script:WinToolState.Busy) {
        $hs.WaitTweaks = $false
        Start-WinToolHomeCheck -Id "tweaks"
    }
    $info = $script:WinToolState.HomeInfoJob
    if ($null -ne $info -and $info.Sync.Done -and $null -eq $hs.Info) {
        $hs.Info = $info.Sync.Data
        if ($null -eq $hs.Info) { $hs.Info = [pscustomobject]@{ Os = ""; Version = ""; Cpu = ""; MemoryTotal = 0; MemoryType = 0; DiskSize = 0; DiskMedia = "" } }
        Update-WinToolHomeCard
    }
    $sampler = $script:WinToolState.HomeSampler
    if ($null -ne $sampler) {
        $sampler.Sync.Paused = ([string]$script:WinToolState.ActiveView -ne "Home")
        $sample = $null
        while ($sampler.Sync.Queue.TryDequeue([ref]$sample)) {
            Add-WinToolHomeSample -Sample $sample
        }
    }
    if ($hs.Phase -eq "analyzing") { Sync-WinToolHomeRunText }
}

function Test-WinToolHomeFixDone {
    $hs = $script:WinToolState.Home
    if ($hs.Phase -ne "fixing") { return }
    if ($hs.Pending.Count -gt 0 -or $hs.WaitTweaks -or $null -ne $script:WinToolState.HomeCleanJob) { return }
    $hs.Phase = "done"
    Sync-WinToolHomeCurrentScore
}

function Start-WinToolHomeClean {
    $hs = $script:WinToolState.Home
    $hs.Phase = "fixing"
    $hs.Pending["junk"] = $true
    $hs.Results.Remove("junk")
    Set-WinToolHomeRow -Row $hs.Rows["junk"] -Status "busy" -Text ("Cleaning" + (Get-WinToolHomeEllipsis)) -Action "off"
    Sync-WinToolHomeHeader
    Write-WinToolLog -Message (Get-WinToolText "msg.junk-files-cleaning-temporary-files-the-recycle-bin-and-") -Level "info"
    if ($script:WinToolHomeNoJobs) { return }
    $script:WinToolState.HomeCleanJob = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "clean") -Argument @(, @(Get-WinToolHomeJunkLocation))
}

function Start-WinToolHomeTweakFix {
    # Uses the Tweaks page's own apply path: same confirmation, same restore point.
    param([switch]$NoConfirm)
    $hs = $script:WinToolState.Home
    if (-not $script:WinToolState.TweakStateRead) { Update-WinToolTweakState }
    $ids = @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended" | ForEach-Object { [string]$_.id })
    $script:WinToolState.TweakRequestStarted = $false
    Request-WinToolTweakOn -Id $ids -Label "the Recommended preset" -NoConfirm:$NoConfirm
    if (-not $script:WinToolState.TweakRequestStarted) {
        $wanted = @{}
        foreach ($id in $ids) { $wanted[$id] = $true }
        $remaining = @($script:WinToolState.TweakRows | Where-Object { $wanted.ContainsKey([string]$_.Id) -and $_.Checkbox.IsChecked -ne $true })
        if ($remaining.Count -eq 0) {
            Sync-WinToolHomeTweakRow
        }
        return $false
    }
    $hs.Phase = "fixing"
    $hs.WaitTweaks = $true
    $hs.Pending["tweaks"] = $true
    $hs.Results.Remove("tweaks")
    Set-WinToolHomeRow -Row $hs.Rows["tweaks"] -Status "busy" -Text ("Applying" + (Get-WinToolHomeEllipsis)) -Action "off"
    Sync-WinToolHomeHeader
    return $true
}

function Get-WinToolHomeJunkPrompt {
    $result = $script:WinToolState.Home.Results["junk"]
    $lines = @($result.Detail | ForEach-Object { "- " + $_ })
    return ("Delete {0} of junk files?`n`n{1}`n`nTemporary files from the last day and files in use are kept." -f (Format-WinToolByteSize -Bytes ([double]$result.Amount)), ($lines -join "`n"))
}

function Invoke-WinToolHomeAction {
    param([Parameter(Mandatory = $true)][string]$Id)
    $hs = $script:WinToolState.Home
    $result = $hs.Results[$Id]
    if ($hs.Phase -ne "done" -or $null -eq $result) { return }
    if ($result.Action -eq "review") {
        Show-WinToolHomeReview -Result $result
        return
    }
    if ($result.Action -ne "fix") { return }
    if ($Id -eq "junk") {
        if (Request-WinToolConfirmation -Message (Get-WinToolHomeJunkPrompt) -Title (Get-WinToolText "msg.junk-files")) {
            Start-WinToolHomeClean
        }
        return
    }
    if ($Id -eq "tweaks") {
        $null = Start-WinToolHomeTweakFix
    }
}

function Invoke-WinToolHomeFixAll {
    $hs = $script:WinToolState.Home
    if ($hs.Phase -ne "done") { return }
    $fixable = @($hs.Results.Values | Where-Object { $_.Fixable })
    if ($fixable.Count -eq 0) { return }
    $lines = New-Object System.Collections.Generic.List[string]
    $junk = $hs.Results["junk"]
    $tweaks = $hs.Results["tweaks"]
    if ($null -ne $junk -and $junk.Fixable) { $lines.Add(("- " + (Get-WinToolText "msg.delete-n-of-junk-files-recent-and-in-use-files-are-kept" (Format-WinToolByteSize -Bytes ([double]$junk.Amount))))) }
    if ($null -ne $tweaks -and $tweaks.Fixable) { $lines.Add(("- " + (Get-WinToolCountText "msg.turn-on-n-recommended-tweaks-restore-point-first" ([int]$tweaks.Amount)))) }
    $ok = Request-WinToolConfirmation -Message ((Get-WinToolText "msg.fix-n-item-s-n-nothing-else-is-changed") -f $lines.Count, ($lines -join "`n")) -Title (Get-WinToolText "ui.HomeFixAll.Content")
    if (-not $ok) { return }
    if ($null -ne $tweaks -and $tweaks.Fixable) { $null = Start-WinToolHomeTweakFix -NoConfirm }
    if ($null -ne $junk -and $junk.Fixable) { Start-WinToolHomeClean }
}

function Show-WinToolHomeReview {
    param([Parameter(Mandatory = $true)]$Result)
    $lines = @($Result.Detail | Select-Object -First 15 | ForEach-Object { "- " + $_ })
    if (@($Result.Detail).Count -gt 15) { $lines += "- ..." }
    $list = $lines -join "`n"
    switch ($Result.Id) {
        "startup" {
            if (Request-WinToolConfirmation -Message ((Get-WinToolText "msg.n-n-open-task-manager-to-turn-programs-off") -f $Result.Text, $list) -Title (Get-WinToolText "msg.startup-programs")) {
                try { Start-Process -FilePath "taskmgr.exe" -ArgumentList (Get-WinToolText "msg.0-startup") } catch { Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-open-task-manager-n") -f $_.Exception.Message) -Level "warn" }
            }
        }
        "drivers" {
            if (Request-WinToolConfirmation -Message ((Get-WinToolText "msg.n-n-open-device-manager") -f $Result.Text, $list) -Title "Drivers") {
                try { Start-Process -FilePath "devmgmt.msc" } catch { Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-open-device-manager-n") -f $_.Exception.Message) -Level "warn" }
            }
        }
        "disk" {
            if (Request-WinToolConfirmation -Message ((Get-WinToolText "msg.n-n-back-up-your-files-soon-open-disks-and-volumes-in-se") -f $Result.Text, $list) -Title (Get-WinToolText "msg.disk-health")) {
                try { Start-Process -FilePath "ms-settings:disksandvolumes" } catch { Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-open-settings-n") -f $_.Exception.Message) -Level "warn" }
            }
        }
    }
}

function Show-WinToolHomeHistory {
    $title = Get-WinToolText "msg.history"
    $items = @(Read-WinToolHomeHistory | Select-Object -Last 10)
    if ($items.Count -eq 0) {
        Show-WinToolNotice -Message (Get-WinToolText "msg.no-analysis-was-saved-yet") -Title $title
        return
    }
    [array]::Reverse($items)
    $lines = @($items | ForEach-Object { "{0}    Score {1}    {2}s" -f (Format-WinToolHomeWhen -Time ([datetime]$_.Time)), [int]$_.Score, [int]$_.Seconds })
    Show-WinToolNotice -Message ($lines -join "`n") -Title $title
}


function Sync-WinToolHomeLocale {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs) { return }
    foreach ($check in @(Get-WinToolHomeCheckList)) {
        $row = $hs.Rows[$check.Id]
        if ($null -eq $row) { continue }
        $row.Name = [string]$check.Name
        if ($null -ne $row.Label) { $row.Label.Text = [string]$check.Name }
    }
    $titles = @{
        memory = (Get-WinToolText "msg.memory")
        disk = (Get-WinToolText "msg.windows-disk")
        pc = (Get-WinToolText "drivers.pcLabel")
    }
    foreach ($key in @("memory", "disk", "pc")) {
        $mini = $hs.Minis[$key]
        if ($null -eq $mini -or $null -eq $mini.TitleText) { continue }
        $mini.TitleText.Text = $titles[$key]
        $mini.TitleText.ToolTip = $titles[$key]
    }
    if ($null -ne $hs.Previous) {
        (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
    }
    Sync-WinToolHomeHeader
}
# endregion

